#!/usr/bin/env node
'use strict';

/**
 * 用法： source <(npx -y louisje/bashrc)
 *
 * 這個腳本會依照目前環境（OS、已安裝工具等）動態組合出一段 bash 設定，
 * 印到 stdout 讓使用者用 source 套用。
 *
 * 內容目前是空殼，之後再逐步補上 alias / prompt / function 等區塊。
 */

const os = require('os');

/**
 * 每個區塊是一個 function，回傳要輸出的 bash 內容（字串），
 * 若回傳空字串或 null，則不輸出該區塊。
 * 之後新增功能時，只要在這裡加新的區塊即可。
 */
const sections = [
  function header() {
    return [
      '# ---------------------------------------------------------------',
      '# Generated by louisje/bashrc',
      `# platform: ${os.platform()}`,
      '# ---------------------------------------------------------------',
    ].join('\n');
  },

  function localBinPath() {
    return [
      'if [[ ":$PATH:" != *":$HOME/.local/bin:"* ]]; then',
      '  export PATH="$HOME/.local/bin:$PATH"',
      'fi',
    ].join('\n');
  },

  function aliases() {
    return [
      "alias sudo='sudo '",
      "alias ..='cd ..'",
    ].join('\n');
  },

  function llAlias() {
    return [
      'if ! command -v ll >/dev/null 2>&1; then',
      '  if command -v eza >/dev/null 2>&1; then',
      "    alias ll='eza -F -lar --sort=modified --color=auto'",
      '  elif command -v lsd >/dev/null 2>&1; then',
      "    alias ll='lsd -Flart --color=auto'",
      '  elif command -v exa >/dev/null 2>&1; then',
      "    alias ll='exa -F -lar --sort=modified --color=auto'",
      '  else',
      "    alias ll='ls -Flart --color'",
      '  fi',
      'fi',
    ].join('\n');
  },

  function zAlias() {
    return [
      'if ! command -v z >/dev/null 2>&1; then',
      "  alias z='cd'",
      'fi',
    ].join('\n');
  },

  function prompt() {
    return "PS1='\\u@\\h:\\w\\$ '";
  }

  // TODO: 常用 function（例如 mkcd, extract）
  // function functions() { ... }
];

function build() {
  return sections
    .map((fn) => fn())
    .filter((chunk) => chunk && chunk.trim().length > 0)
    .join('\n\n');
}

function main() {
  process.stdout.write(build() + '\n');
}

main();
